            this.elements.myActionsTitle.innerHTML = `<i class="fa fa-child mr-2"></i> ${titleEmoji} ${titleText}`;
            this.elements.myOptionsList.innerHTML = renderOptionList(myChoiceData.选项);
        } else {
            this.elements.myActionsBlock.style.display = 'none';
        }
        // Render NPC's Invitations
        if (invitationData && invitationData.选项?.length) {
            this.elements.invitationBlock.style.display = 'block';
            const titleEmoji = String(invitationData.标题 || '').match(/💌|😈/)?.[0] || '😈';
            const inviterName = String(invitationData.行动方 || '她').replace(/😈/g, '').trim();
            const titleText = (invitationData.标题 || '的邀请...').replace(/💌|😈/g, '').trim();
            this.elements.invitationTitle.innerHTML = `<i class="fa fa-commenting-o mr-2"></i> ${titleEmoji} <b>${inviterName}</b>${titleText}`;
            this.elements.invitationOptionsList.innerHTML = renderOptionList(invitationData.选项);
        } else {
            this.elements.invitationBlock.style.display = 'none';
        }
        // Fallback if no options at all
        if (!myChoiceData && !invitationData) {
            this.elements.myActionsBlock.style.display = 'block';
            this.elements.myActionsTitle.innerHTML = '';
            this.elements.myOptionsList.innerHTML = this.createEmptyState('现在不知道该玩什么...');
        }
    }
    updateDynamicStyles() {
        const tensionLevel = parseInt((this.findData('游戏记录.我的心跳') || '').match(/紧张指数:\s*(\d+)/)?.[1] || 0, 10);
        this.themeManager.setTense(tensionLevel > 60);
