            <div class="grid grid-cols-1 md:grid-cols-2 gap-px" style="background-color: var(--border);">
                <div id="story-info-panel" class="p-3" style="background-color: var(--bg);"></div>
                <div id="game-record-panel" class="p-3" style="background-color: var(--bg);"></div>
            </div>
            <div class="border-t theme-transition">
                <details class="w-full group" open>
                    <summary class="w-full px-4 py-3 font-semibold cursor-pointer flex justify-between items-center list-none hover:opacity-80">
                        <span class="flex items-center"><i class="fa fa-users mr-2"></i> 谁在这里呀？</span><i class="fa fa-chevron-down transition-transform duration-300 group-open:rotate-180"></i>
                    </summary>
                    <div id="characters-container" class="p-3 space-y-3 overflow-hidden"></div>
                </details>
            </div>
            <!-- ### ACTION SECTION (MODIFIED) ### -->
            <div id="actions-section" class="border-t theme-transition rounded-b-2xl">
                <!-- Player's Options -->
                <div id="my-actions-block" class="px-4 pt-3 pb-2">
                     <h3 id="my-actions-title" class="font-bold flex items-center text-base"></h3>
                     <ul id="my-options-list" class="list-none space-y-2 text-sm pl-1 py-2"></ul>
                </div>
                <!-- NPC's Invitation Options -->
                <div id="invitation-block" class="px-4 pt-2 pb-4 border-t-2 border-dashed" style="display: none;">
                     <h3 id="invitation-title" class="font-bold flex items-center text-base"></h3>
