<script>
document.addEventListener('DOMContentLoaded', () => {
    const triggerQuickReply = text => {
        if (text && text.trim() && !['…', '...'].includes(text.trim())) {
            typeof triggerSlash === 'function' ? triggerSlash(`/send ${text}|/trigger`) : console.log('SillyTavern [DEV]:', text);
        }
    };
    const storyRenderer = new StoryRenderer('yaml-data-source');
    storyRenderer.init();

    // ### EVENT LISTENER (MODIFIED) ###
    document.getElementById('actions-section').addEventListener('click', e => {
        const optionItem = e.target.closest('li.action-option');
        if (optionItem) { // Simplified check for any valid option item
            triggerQuickReply(optionItem.getAttribute('data-full-text'));
        }
    });
});

class ThemeManager {
    constructor(switcherId, containerId) { this.container = document.getElementById(containerId); this.themeButtons = document.querySelectorAll(`#${switcherId} .theme-btn`); this.currentTheme = localStorage.getItem('storyTheme') || 'day'; this.isTense = false; }
    init() { this.switchToTheme(this.currentTheme, false); this.themeButtons.forEach(button => { button.addEventListener('click', () => { if (this.isTense) return; const theme = button.getAttribute('data-theme'); this.currentTheme = theme; localStorage.setItem('storyTheme', theme); this.switchToTheme(theme, false); }); }); }
    switchToTheme(theme, isForced) { this.container.className = 'status-block mb-4 rounded-2xl shadow-lg overflow-hidden border theme-transition'; this.container.classList.add(isForced ? 'tense-mode' : `${theme}-mode`); this.themeButtons.forEach(btn => { btn.classList.toggle('active', btn.getAttribute('data-theme') === theme && !isForced); btn.disabled = isForced; btn.style.cursor = isForced ? 'not-allowed' : 'pointer'; }); }
    setTense(tense) { const actionsSection = document.getElementById('actions-section'); if (tense && !this.isTense) { this.isTense = true; this.switchToTheme('tense', true); actionsSection?.classList.add('animate-pulse'); } else if (!tense && this.isTense) { this.isTense = false; this.switchToTheme(this.currentTheme, false); actionsSection?.classList.remove('animate-pulse'); } }
}

// ### StoryRenderer CLASS (MODIFIED) ###
class StoryRenderer {
    constructor(dataSourceId) {
        this.yamlData = null;
        try { const scriptElement = document.getElementById(dataSourceId); if (!scriptElement || !scriptElement.textContent.trim()) throw new Error('YAML数据源为空'); this.yamlData = jsyaml.load(scriptElement.textContent); } catch (error) { this.handleError(error); }
        this.themeManager = new ThemeManager('theme-switcher', 'status-container');
        this.elements = {
            storyInfoPanel: document.getElementById('story-info-panel'),
            gameRecordPanel: document.getElementById('game-record-panel'),
            charactersContainer: document.getElementById('characters-container'),
            myActionsBlock: document.getElementById('my-actions-block'),
            myActionsTitle: document.getElementById('my-actions-title'),
            myOptionsList: document.getElementById('my-options-list'),
            invitationBlock: document.getElementById('invitation-block'),
            invitationTitle: document.getElementById('invitation-title'),
            invitationOptionsList: document.getElementById('invitation-options-list')
        };
    }
    init() { if (this.yamlData) { this.themeManager.init(); this.renderAll(); } }
    findData(path) { return path.split('.').reduce((obj, key) => obj?.[key], this.yamlData.状态栏); }
    renderAll() { this.renderInfoPanels(); this.renderCharacters(); this.renderActionOptions(); this.updateDynamicStyles(); }
    renderInfoPanels() { const createPanelContent = (data, title, icon, fields) => { if (!data) return this.createEmptyState(`无${title}`); const fieldHTML = fields.map(field => `<div id="${field.id || ''}">${data[field.key] || field.fallback}</div>`).join(''); return `<div class="font-bold mb-2 flex items-center"><i class="fa ${icon} mr-2 title-icon"></i> ${title}</div><div class="text-sm space-y-1 pl-5">${fieldHTML}</div>`; }; this.elements.storyInfoPanel.innerHTML = createPanelContent(this.findData('故事信息'), '故事信息', 'fa-info-circle', [{ key: '发生时间', fallback: '时间未知' }, { key: '发生地点', fallback: '地点未知' }]); this.elements.gameRecordPanel.innerHTML = createPanelContent(this.findData('游戏记录'), '游戏记录', 'fa-trophy', [{ key: '被大姐姐抓到的次数', fallback: '还没被抓到过...' }, { id: 'heartbeat-display', key: '我的心跳', fallback: '心跳很平稳' }]); }
    renderCharacters() { const characters = this.findData('今天遇到了谁'); this.elements.charactersContainer.innerHTML = ''; if (!characters?.length) { this.elements.charactersContainer.innerHTML = this.createEmptyState('这里还没有人哦'); return; } characters.forEach(char => this.elements.charactersContainer.appendChild(this.createCharacterCard(char.登场人物))); }
    createCharacterCard(data) { const card = document.createElement('div'); card.className = 'rounded-xl border p-3.5 shadow-sm character-card theme-transition'; const attributes = Object.entries(data).filter(([key]) => key !== '名字'); card.innerHTML = `<h3 class="font-bold text-lg mb-2 pb-1 border-b theme-transition">${data.名字 || '神秘人物'}</h3><ul class="space-y-2 text-sm">${attributes.map(([k, v]) => this.createAttributeItem(k, v)).join('')}</ul>`; return card; }
    createAttributeItem(key, value) { const emojiRegex = /([\uE000-\uF8FF]|\uD83C[\uDC00-\uDFFF]|\uD83D[\uDC00-\uDFFF]|[\u2011-\u26FF]|\uD83E[\uDD10-\uDDFF])/; const valueStr = String(value); const emoji = valueStr.match(emojiRegex)?.[0] || '🔸'; const text = valueStr.replace(emojiRegex, '').trim(); const style = `style="color:var(--primary);"`; if (key.includes("秘密")) { return `<li class="italic p-2 rounded-lg border-l-4 theme-transition secret-thought"><span class="opacity-70">${emoji} ${key}: ${text}</span></li>`; } return `<li><span class="font-semibold" ${style}>${emoji} ${key}:</span> ${text}</li>`; }
    renderActionOptions() {
        const actionsData = this.findData('行动抉择');
        const myChoiceData = actionsData?.['我想怎么玩'];
        const invitationData = actionsData?.['大姐姐的邀请'];
        const renderOptionList = (options) => {
            return (options || []).map(optionText => {
                const fullText = optionText.trim();
                const cleanText = fullText.replace(/\[.*?\]/g, '').trim();
                const category = (fullText.match(/\[(.*?)\]/)?.[1] || '').replace(/[？?!...]/g, '');
                return `<li class="p-2 border-l-2 rounded-r-md cursor-pointer action-option theme-transition flex justify-between items-center" data-full-text="${fullText}">
                            <span class="flex-grow pr-2"><i class="fa fa-hand-o-right mr-2"></i>${cleanText}</span>
                            ${category ? `<span class="category-tag text-xs px-2 py-0.5 rounded-full whitespace-nowrap">${category}</span>` : ''}
                        </li>`;
            }).join('');
        };
        // Render Player's Options
        if (myChoiceData && myChoiceData.选项?.length) {
            this.elements.myActionsBlock.style.display = 'block';
            const titleEmoji = String(myChoiceData.标题 || '').match(/🎲|🤔/)?.[0] || '🤔';
            const titleText = (myChoiceData.标题 || '我应该怎么办呀？').replace(/🎲|🤔/g, '').trim();
            this.elements.myActionsTitle.innerHTML = `<i class="fa fa-child mr-2"></i> ${titleEmoji} ${titleText}`;
            this.elements.myOptionsList.innerHTML = renderOptionList(myChoiceData.选项);
        } else {
            this.elements.myActionsBlock.style.display = 'none';
        }
        // Render NPC's Invitations
        if (invitationData && invitationData.选项?.length) {
            this.elements.invitationBlock.style.display = 'block';
            const titleEmoji = String(invitationData.标题 || '').match(/💌|😈/)?.[0] || '😈';
            const inviterName = String(invitationData.行动方 || '她').replace(/😈/g, '').trim();
            const titleText = (invitationData.标题 || '的邀请...').replace(/💌|😈/g, '').trim();
            this.elements.invitationTitle.innerHTML = `<i class="fa fa-commenting-o mr-2"></i> ${titleEmoji} <b>${inviterName}</b>${titleText}`;
            this.elements.invitationOptionsList.innerHTML = renderOptionList(invitationData.选项);
        } else {
            this.elements.invitationBlock.style.display = 'none';
        }
        // Fallback if no options at all
        if (!myChoiceData && !invitationData) {
            this.elements.myActionsBlock.style.display = 'block';
            this.elements.myActionsTitle.innerHTML = '';
            this.elements.myOptionsList.innerHTML = this.createEmptyState('现在不知道该玩什么...');
        }
    }
    updateDynamicStyles() {
        const tensionLevel = parseInt((this.findData('游戏记录.我的心跳') || '').match(/紧张指数:\s*(\d+)/)?.[1] || 0, 10);
        this.themeManager.setTense(tensionLevel > 60);
        const heartbeatDisplay = document.getElementById('heartbeat-display');
        if (heartbeatDisplay) {
            heartbeatDisplay.classList.toggle('animate-heartbeat', tensionLevel > 60);
        }
    }
    createEmptyState(message) { return `<div class="text-center py-4 opacity-60"><i class="fa fa-info-circle mr-1"></i>${message}</div>`; }
    handleError(error) { console.error('渲染错误:', error); document.body.innerHTML = `<div class="m-4 bg-red-900/20 border border-red-800/30 text-red-400 px-4 py-3 rounded"><strong>加载失败: </strong><span>${error.message}</span></div>`; }
}
</script>
</body>
</html>
